-- 554: Original BrillaPrep WASSCE Social Studies sprint 3 beta questions, part 1 of 15 (batch wassce-social-studies-sprint3-001).
-- Curriculum-aligned practice content; not official WAEC examination material.
PRAGMA foreign_keys = ON;
CREATE TABLE IF NOT EXISTS _migration_554_guard (valid INTEGER NOT NULL CHECK (valid = 1));
DELETE FROM _migration_554_guard;
INSERT INTO _migration_554_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM questions q WHERE q.id = 'q_was_soc_s3_001' AND NOT (q.topic_id IS 'topic_wassce_p2_soc_gov' AND q.subject_id IS 'subj_wassce_social' AND q.exam_type_id IS 'exam_wassce' AND q.paper_type_id IS NULL AND q.past_paper_id IS NULL AND q.question_text IS 'Which system of government gives citizens the power to choose their leaders through regular, free elections?' AND q.question_type IS 'multiple_choice' AND q.round_type IS NULL AND q.options IS '["A. Democracy","B. Autocracy","C. Monarchy","D. Military rule"]' AND q.correct_answer IS 'A' AND q.explanation IS 'Democracy vests supreme power in the people, who exercise it directly or through freely elected representatives chosen in periodic elections. (An autocracy concentrates power in one ruler, a monarchy vests it in a hereditary sovereign, and military rule seizes power by force — none of these rests on elections.) Therefore the correct answer is A: Democracy.' AND q.difficulty IS 'easy' AND q.points IS '1' AND q.marks IS '1' AND q.time_limit IS '90' AND q.question_number IS NULL AND q.section IS NULL AND q.is_compulsory IS '1' AND q.image_url IS NULL AND q.syllabus_topic_id IS NULL AND q.command_word IS 'Identify' AND q.assessment_objective IS 'AO1' AND q.source_paper_code IS NULL AND q.source_question_number IS NULL AND q.exam_board_id IS 'board_waec')) AND NOT EXISTS (SELECT 1 FROM question_content_releases r WHERE r.question_id = 'q_was_soc_s3_001' AND NOT (r.batch_id IS 'wassce-social-studies-sprint3-001' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep curriculum-aligned WASSCE Social Studies practice questions; not official WAEC (West African Examinations Council) examination material. Use the enabled feedback channel to report corrections.' AND r.source_url IS 'https://nacca.gov.gh/secondary-education-curriculum/' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1)) THEN 1 ELSE 0 END;
INSERT INTO _migration_554_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM questions q WHERE q.id = 'q_was_soc_s3_002' AND NOT (q.topic_id IS 'topic_wassce_p2_soc_gov' AND q.subject_id IS 'subj_wassce_social' AND q.exam_type_id IS 'exam_wassce' AND q.paper_type_id IS NULL AND q.past_paper_id IS NULL AND q.question_text IS 'How many arms of government does the 1992 Constitution of Ghana establish?' AND q.question_type IS 'multiple_choice' AND q.round_type IS NULL AND q.options IS '["A. Two","B. Three","C. Four","D. Five"]' AND q.correct_answer IS 'B' AND q.explanation IS 'The 1992 Constitution establishes three arms of government: the Executive (President and ministers), the Legislature (Parliament) and the Judiciary (the courts). (Four wrongly counts the civil service, which supports the Executive but is not an arm of government.) Therefore the correct answer is B: Three.' AND q.difficulty IS 'easy' AND q.points IS '1' AND q.marks IS '1' AND q.time_limit IS '90' AND q.question_number IS NULL AND q.section IS NULL AND q.is_compulsory IS '1' AND q.image_url IS NULL AND q.syllabus_topic_id IS NULL AND q.command_word IS 'State' AND q.assessment_objective IS 'AO1' AND q.source_paper_code IS NULL AND q.source_question_number IS NULL AND q.exam_board_id IS 'board_waec')) AND NOT EXISTS (SELECT 1 FROM question_content_releases r WHERE r.question_id = 'q_was_soc_s3_002' AND NOT (r.batch_id IS 'wassce-social-studies-sprint3-001' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep curriculum-aligned WASSCE Social Studies practice questions; not official WAEC (West African Examinations Council) examination material. Use the enabled feedback channel to report corrections.' AND r.source_url IS 'https://nacca.gov.gh/secondary-education-curriculum/' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1)) THEN 1 ELSE 0 END;
INSERT INTO _migration_554_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM questions q WHERE q.id = 'q_was_soc_s3_003' AND NOT (q.topic_id IS 'topic_wassce_p2_soc_gov' AND q.subject_id IS 'subj_wassce_social' AND q.exam_type_id IS 'exam_wassce' AND q.paper_type_id IS NULL AND q.past_paper_id IS NULL AND q.question_text IS 'Which arm of government is responsible for interpreting the laws of Ghana?' AND q.question_type IS 'multiple_choice' AND q.round_type IS NULL AND q.options IS '["A. The Executive","B. The Legislature","C. The Judiciary","D. The Electoral Commission"]' AND q.correct_answer IS 'C' AND q.explanation IS 'The Judiciary — the courts headed by the Chief Justice — interprets and applies the laws. The Legislature makes the laws and the Executive implements and enforces them, so those options swap the functions of the three arms. The Electoral Commission only conducts elections. Therefore the correct answer is C: The Judiciary.' AND q.difficulty IS 'easy' AND q.points IS '1' AND q.marks IS '1' AND q.time_limit IS '90' AND q.question_number IS NULL AND q.section IS NULL AND q.is_compulsory IS '1' AND q.image_url IS NULL AND q.syllabus_topic_id IS NULL AND q.command_word IS 'Identify' AND q.assessment_objective IS 'AO1' AND q.source_paper_code IS NULL AND q.source_question_number IS NULL AND q.exam_board_id IS 'board_waec')) AND NOT EXISTS (SELECT 1 FROM question_content_releases r WHERE r.question_id = 'q_was_soc_s3_003' AND NOT (r.batch_id IS 'wassce-social-studies-sprint3-001' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep curriculum-aligned WASSCE Social Studies practice questions; not official WAEC (West African Examinations Council) examination material. Use the enabled feedback channel to report corrections.' AND r.source_url IS 'https://nacca.gov.gh/secondary-education-curriculum/' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1)) THEN 1 ELSE 0 END;
INSERT INTO _migration_554_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM questions q WHERE q.id = 'q_was_soc_s3_004' AND NOT (q.topic_id IS 'topic_wassce_p2_soc_gov' AND q.subject_id IS 'subj_wassce_social' AND q.exam_type_id IS 'exam_wassce' AND q.paper_type_id IS NULL AND q.past_paper_id IS NULL AND q.question_text IS 'In which year did Ghana’s Fourth Republic come into being?' AND q.question_type IS 'multiple_choice' AND q.round_type IS NULL AND q.options IS '["A. 1992","B. 1957","C. 1979","D. 1993"]' AND q.correct_answer IS 'D' AND q.explanation IS 'Although the Constitution was approved by referendum in April 1992, the Fourth Republic was inaugurated on 7 January 1993 when the first President and Parliament under it took office. (1992 is the referendum year — the common mix-up; 1957 is independence; 1979 began the short-lived Third Republic.) Therefore the correct answer is D: 1993.' AND q.difficulty IS 'easy' AND q.points IS '1' AND q.marks IS '1' AND q.time_limit IS '90' AND q.question_number IS NULL AND q.section IS NULL AND q.is_compulsory IS '1' AND q.image_url IS NULL AND q.syllabus_topic_id IS NULL AND q.command_word IS 'State' AND q.assessment_objective IS 'AO1' AND q.source_paper_code IS NULL AND q.source_question_number IS NULL AND q.exam_board_id IS 'board_waec')) AND NOT EXISTS (SELECT 1 FROM question_content_releases r WHERE r.question_id = 'q_was_soc_s3_004' AND NOT (r.batch_id IS 'wassce-social-studies-sprint3-001' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep curriculum-aligned WASSCE Social Studies practice questions; not official WAEC (West African Examinations Council) examination material. Use the enabled feedback channel to report corrections.' AND r.source_url IS 'https://nacca.gov.gh/secondary-education-curriculum/' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1)) THEN 1 ELSE 0 END;
INSERT OR IGNORE INTO questions (id, topic_id, subject_id, exam_type_id, paper_type_id, past_paper_id, question_text, question_type, round_type, options, correct_answer, explanation, difficulty, points, marks, time_limit, question_number, section, is_compulsory, image_url, syllabus_topic_id, command_word, assessment_objective, source_paper_code, source_question_number, exam_board_id) VALUES ('q_was_soc_s3_001', 'topic_wassce_p2_soc_gov', 'subj_wassce_social', 'exam_wassce', NULL, NULL, 'Which system of government gives citizens the power to choose their leaders through regular, free elections?', 'multiple_choice', NULL, '["A. Democracy","B. Autocracy","C. Monarchy","D. Military rule"]', 'A', 'Democracy vests supreme power in the people, who exercise it directly or through freely elected representatives chosen in periodic elections. (An autocracy concentrates power in one ruler, a monarchy vests it in a hereditary sovereign, and military rule seizes power by force — none of these rests on elections.) Therefore the correct answer is A: Democracy.', 'easy', '1', '1', '90', NULL, NULL, '1', NULL, NULL, 'Identify', 'AO1', NULL, NULL, 'board_waec');
