INSERT OR IGNORE INTO questions (id, topic_id, subject_id, exam_type_id, paper_type_id, past_paper_id, question_text, question_type, round_type, options, correct_answer, explanation, difficulty, points, marks, time_limit, question_number, section, is_compulsory, image_url, syllabus_topic_id, command_word, assessment_objective, source_paper_code, source_question_number, exam_board_id) VALUES ('q_was_soc_s3_004', 'topic_wassce_p2_soc_gov', 'subj_wassce_social', 'exam_wassce', NULL, NULL, 'In which year did Ghana’s Fourth Republic come into being?', 'multiple_choice', NULL, '["A. 1992","B. 1957","C. 1979","D. 1993"]', 'D', 'Although the Constitution was approved by referendum in April 1992, the Fourth Republic was inaugurated on 7 January 1993 when the first President and Parliament under it took office. (1992 is the referendum year — the common mix-up; 1957 is independence; 1979 began the short-lived Third Republic.) Therefore the correct answer is D: 1993.', 'easy', '1', '1', '90', NULL, NULL, '1', NULL, NULL, 'State', 'AO1', NULL, NULL, 'board_waec');
